// Every number that decides how the game plays, in one place. The Bedrock scripts
// get these through scripts/data.js and the Java mod through
// data/lasertag/rules.json (both generated by tools/build.mjs).
//
// Times are in seconds, distances in blocks, heat in percent. Lasers never hurt:
// a hit tags the vest, the wearer is out for a few seconds and then back in.

export const TEAMS = ['red', 'blue', 'green', 'yellow'];

export const RULES = {
  teams: TEAMS,
  // Team colours: [r, g, b] 0–255 (beams, particles, vests, blocks) and the chat colour code.
  colours: {
    red: { rgb: [255, 48, 64], chat: 'c' },
    blue: { rgb: [40, 140, 255], chat: '9' },
    green: { rgb: [60, 230, 90], chat: 'a' },
    yellow: { rgb: [255, 216, 40], chat: 'e' },
  },

  // The lasers: hitscan rays. `heat` is added per shot; at 100 the gun overheats and
  // can't fire until it has cooled right down. `cooldown` is the time between shots.
  guns: {
    laser_pistol: { range: 24, cooldown: 0.25, heat: 9, rays: 1, spread: 0.6, points: 1 },
    laser_blaster: { range: 40, cooldown: 0.45, heat: 14, rays: 1, spread: 0.3, points: 1 },
    laser_rifle: { range: 80, cooldown: 1.4, heat: 34, rays: 1, spread: 0, points: 1, zoom: true },
    scatter_laser: { range: 12, cooldown: 0.9, heat: 30, rays: 5, spread: 7, points: 1 },
  },
  heat: { max: 100, coolPerSecond: 35, overheatCoolPerSecond: 25 },
  grenade: { id: 'pulse_grenade', radius: 3.5, fuse: 0 },

  tag: {
    // Stunned for this long after a tag: can't move or fire, a sign above the head,
    // then back at a spawn pad.
    down: 10,
    // Can't be tagged for this long after coming back.
    protect: 3,
    // Two or more tags within this many seconds make a double, triple … tag.
    multiWindow: 3,
  },
  streaks: [[3, 'on_a_roll'], [5, 'unstoppable'], [8, 'legendary']],
  multis: [[2, 'double'], [3, 'triple'], [4, 'quad']],

  // Game modes: what scores, and the default score limit (0 = time only).
  modes: {
    team_deathmatch: { teams: true, scoreLimit: 25 },
    free_for_all: { teams: false, scoreLimit: 15 },
    capture_the_flag: { teams: true, scoreLimit: 3 },
    king_of_the_hill: { teams: true, scoreLimit: 120 },
  },
  // Choices on the game console.
  console: {
    minutes: [3, 5, 10, 15],
    startMinutes: 5,
    botsPerTeam: 4,
    countdown: 5,
    // Everyone this close to the console when the game starts is in it.
    reach: 96,
    warnAt: 60,
  },

  flag: { touch: 1.6, returnAfter: 30 },
  // A control point is taken by standing next to it: `capture` points of progress, one per
  // second per player (at most `maxPush`). Each point a team holds scores once a second.
  point: { radius: 3.5, capture: 6, maxPush: 3, decay: 1 },

  powerups: {
    recharge: 30,
    touch: 1.5,
    kinds: {
      rapid_fire: { seconds: 10 },
      shield: { seconds: 30 },
      speed: { seconds: 10 },
      double_points: { seconds: 15 },
    },
  },

  // A smoke machine pumps haze for `burst` seconds, then rests for `pause` seconds; all
  // machines keep the same beat. `puffs` clouds every half second, drifting up to `drift`.
  smoke: { burst: 4, pause: 8, puffs: 3, drift: 0.08 },

  // A siren goes off when a player's laser hits it: for `seconds` the lights go out for
  // everyone within `radius` blocks and a strobe flashes every `flash` ticks. Then it
  // needs `recharge` seconds before it can go off again.
  siren: { seconds: 10, recharge: 180, radius: 48, flash: 4 },

  bot: {
    health: 20,
    sight: 32,
    // Seconds between the AI's shots. How good a bot is, picked on the console: `fire` is the
    // chance it takes a shot the AI offers, `accuracy` the chance it hits (it aims a little off
    // otherwise).
    interval: [0.8, 1.6],
    skills: {
      easy: { fire: 0.45, accuracy: 0.3 },
      normal: { fire: 0.75, accuracy: 0.55 },
      hard: { fire: 1, accuracy: 0.8 },
    },
    skill: 'normal',
    range: 20,
  },
};
